# Purpose: Switch-RegEx — General-purpose PowerShell utilities.
$array = "123.456","abcdefg","THX-138","Rhubarb", "0414 987 058","MicroSoft"switch -RegEx ($array){ "^\d{1,3}\."        {write-host "'$_' begins with a numeric then a dot"} "\d{3}$"            {write-host "'$_' ends with three digits"} "[A-Z]-\d+"         {write-host "'$_' contains ALPHA-NUMERIC dash numbers"} "\d+\s\d{3}\s\d{3}" {write-host "'$_' looks like a phone number"} default             {write-host "'$_' had no match..."}}# NOTE: more advanced, add in something for luke@contoso.com.au# �\w+\@\w+[\.\w+]+�  �looks like an email address�